def fmt(x):
    return f'{x:.6g}' if isinstance(x, (int, float)) else str(x)

def write_tables(r3):
    headers = ['Kant', "Gap/level", "now decided (limited)", 'Egen design', "The remaining labs", "Path"]
    text = ["# Gap × Decision × measurement", '', "Each line distinguishes a source bound or calculated partial gate from a full physical query. UNKNOWN uncertainty is not a zero. No clinical decisions are certified.", '', '| ' + ' | '.join(headers) + ' |', '|' + '|'.join(['---'] * len(headers)) + '|']
    for q in r3['numeric_gap_rows']:
        row = [q['edge_id'], fmt(q['gap']) + ' ' + q['unit'] + ' / ' + q['resolution'], q['decided_now'], q['own_design'], q['lab_remainder'] or 'UNKNOWN', q['route']]
        text.append('| ' + ' | '.join((str(x).replace('|', '/').replace('\n', ' ') for x in row)) + ' |')
    text += ['', '## Fysiskt blockerade grupper', '', "All 30 groups below have at least one of the 51 physically blocked edges. The table is a remaining measurement contract, not 30 orders. Activation requires concrete decision margin, correct observation support and actual quote. The minimum n for physical precision and real decisions that reverses per specimen is UNKNOWN .", '', "| Group | Edges/single measurement type | Egen design | What remains | Cost |", '|---|---:|---|---|---|']
    for q in r3['physical_group_rows']:
        cost = str(q['operator_hour_planning_interval']) + ' h PHENOMENOLOGICAL' if q['operator_hour_planning_interval'] else "UNKNOWN ; quotation required"
        text.append(f"| {q['id']} {q['name']} | {q['touch_count']} / {len(q['alone_type_ready_edges'])} | {q['own_design']} | {q['remaining_reason']} | {cost} |")
    text += ['', "Precise edge amounts, specimen/state, remaining model requirements and time scale are available in results.json. Point and region data are first aggregated in the consumer.", '']
    (ROOT / 'GAP_DECISION_TABLE.md').write_text('\n'.join(text))
    with (ROOT / 'raw/GAP_DECISION_TABLE.csv').open('w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['edge_id', 'gap', 'unit', 'resolution', 'route', 'decided_now', 'own_design', 'lab_remainder'])
        writer.writeheader()
        writer.writerows(({k: q.get(k) for k in writer.fieldnames} for q in r3['numeric_gap_rows']))

def figure(r1, r2, r3):
    plt.rcParams.update({'font.size': 9})
    (fig, axs) = plt.subplots(2, 2, figsize=(12, 9), layout='constrained')
    ax = axs[0, 0]
    xx = np.arange(3)
    names = ['B', 'D', 'E']
    baseline = [q['baseline_max_abs_error_HU_ref'] for q in r1['cbct_repeat_test']]
    means = [q['repeat_mean_max_abs_error_HU_ref'] for q in r1['cbct_repeat_test']]
    held = [max((q['max_abs_HU_ref'] for q in r2['calibration']['held_rows'] if q['device'].endswith(n))) for n in names]
    ax.bar(xx - 0.24, baseline, 0.24, label='Original 2 anchors')
    ax.bar(xx, means, 0.24, label='Mean of 3 repeats')
    ax.bar(xx + 0.24, held, 0.24, label='Selected 3 anchors, held protocols')
    ax.axhline(40, color='black', ls='--', label='Frozen 40 HU_ref gate')
    ax.set_xticks(xx, ['Elekta ' + x for x in names])
    ax.set_ylabel('Worst error (HU_ref)')
    ax.set_title('PER_SURFACE_REGION: repeats retain calibration bias')
    ax.legend(fontsize=7)
    ax = axs[0, 1]
    rows = r2['thermal']['rows']
    y = np.arange(9)
    for (i, q) in enumerate(rows):
        (a, b) = q['current_with_drift95_interval_degC']
        ax.plot([a, b], [i, i], color='#bbb', lw=5)
        (a, b) = q['current_simultaneous95_interval_degC']
        ax.plot([a, b], [i, i], color='#2549a3', lw=2)
        ax.plot(q['dry_minus_cooled_degC'], i, 'o', color='#2549a3', ms=4)
    ax.axvline(0, color='black', ls='--')
    ax.set_yticks(y, [f"{q['frequency_Hz']} Hz / {q['energy_mJ']} mJ" for q in rows])
    ax.invert_yaxis()
    ax.set_xlabel('Dry minus cooled temperature (°C)')
    ax.set_title('POPULATION: nominal simultaneous 95% sampling intervals\nBlue sampling; grey ±0.40°C drift; inferred n=4/group', fontsize=10)
    ax = axs[1, 0]
    vals = [r2['thermal']['optimally_allocated_specimens_no_drift'], r2['thermal']['uniform_allocation_specimens_no_drift']]
    ax.bar(['Contrast-specific\ninteger allocation', 'Equal allocation\nall 18 groups'], vals, color=['#297966', '#9caaaa'])
    for (i, v) in enumerate(vals):
        ax.text(i, v + 5, str(v), ha='center')
    ax.set_ylim(0, max(vals) * 1.15)
    ax.set_ylabel('Projected independent specimen endpoints')
    ax.set_title('PHENOMENOLOGICAL plan: same sampling target')
    ax.text(0.04, 0.03, 'Normal plug-in SD; zero differential drift\nCount reduction is a simulation, not observed lab saving', transform=ax.transAxes, fontsize=8)
    ax = axs[1, 1]
    ax.axvspan(np.exp(-0.2), np.exp(0.2), color='#dfebe0', label='Frozen fixed-prediction acceptance')
    for (i, q) in enumerate(r3['force_intervals'][:3]):
        (lo, hi) = np.array(q['simultaneous95_response_mean_interval_N']) / q['predicted_N']
        m = q['observed_N'] / q['predicted_N']
        ax.plot([lo, hi], [i, i], color='#297966' if q['source_mean_gate'] == 'PASS' else '#a45b21', lw=3)
        ax.plot(m, i, 'o', color='black', ms=4)
    ax.set_yticks(range(3), ['5Y no abrasion', '5Y RMGI', '5Y resin'])
    ax.invert_yaxis()
    ax.set_xlabel('Response mean / fixed predicted force')
    ax.set_title('POPULATION: uncertainty reopens 2 of 3 mean gates\nConditional balanced n=10; fixed predictor', fontsize=10)
    ax.legend(fontsize=7)
    fig.suptitle('X81 — decision uncertainty is more than residual magnitude', fontsize=14)
    fig.savefig(ROOT / 'figures/DECISION_WITHIN_NOISE.png', dpi=160)
    fig.savefig(ROOT / 'figures/DECISION_WITHIN_NOISE.svg')
    plt.close(fig)

